import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-128: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short128', durationInSeconds: 43.7, fps: 30, width: 1080, height: 1920 };

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

type Row = { k: string; v: string; good?: boolean; bad?: boolean };
const Line: React.FC<Row> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 24, fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

// [start_s, name, tagline, chip, tone, rows]
const HOOK_END = 3.2;
const CTA_S = 40.3;
const BEATS: { s: number; name: string; tag: string; chip: string; tone: 'bad' | 'good' | 'neutral'; rows: Row[] }[] = [
  { s: 3.2, name: 'Gemini 3.5 Flash-Lite', tag: 'Cache storage.', chip: '$1.00', tone: 'bad', rows: [{ k: 'storage /1M /hr', v: '$1.00', bad: true }] },
  { s: 10.5, name: 'Gemini 3.8 Flash', tag: 'Cache storage.', chip: '$0.50', tone: 'good', rows: [{ k: 'storage /1M /hr', v: '$0.50', good: true }] },
  { s: 14.4, name: 'Flash is pricier', tag: 'Input per 1M.', chip: 'INPUT', tone: 'neutral', rows: [{ k: '3.8 Flash', v: '$0.75' }, { k: '3.5 Flash-Lite', v: '$0.30' }] },
  { s: 21.0, name: 'But storage is half', tag: 'Per 1M per hour.', chip: '1/2', tone: 'good', rows: [{ k: '3.8 Flash', v: '$0.50', good: true }, { k: '3.5 Flash-Lite', v: '$1.00', bad: true }] },
  { s: 23.9, name: '1M tokens, one day', tag: 'Storage only.', chip: '$12 v $24', tone: 'neutral', rows: [{ k: '3.8 Flash', v: '$12.00', good: true }, { k: '3.5 Flash-Lite', v: '$24.00', bad: true }] },
  { s: 30.4, name: 'Until Dec 31', tag: 'Then it changes.', chip: 'DEC 31', tone: 'neutral', rows: [{ k: 'Flash storage', v: '$0.50' }, { k: 'ends', v: 'Dec 31, 2026' }] },
  { s: 33.5, name: 'From Jan 1, 2027', tag: 'Flash catches up.', chip: '$1.00', tone: 'bad', rows: [{ k: '3.8 Flash storage', v: '$1.00', bad: true }, { k: 'Flash-Lite', v: '$1.00' }] },
];

const Short128: React.FC = () => {
  const frame = useCurrentFrame();
  const CTA = secToFrame(CTA_S);
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{ text: 'CHEAPER GEMINI' }, { text: '2X TO CACHE', accent: true }];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={secToFrame(HOOK_END)}>
        <CoverImage src="projects/short-128/cover.png" out={secToFrame(HOOK_END) - 10} />
        <HookTitle hold onDark kicker="GEMINI CACHE" lines={lines} />
      </FadeOut>
      {BEATS.map((b, i) => {
        const end = i + 1 < BEATS.length ? BEATS[i + 1].s : CTA_S;
        const prev = i === 0 ? HOOK_END : b.s;
        return (
          <FadeOut key={i} at={secToFrame(end)}>
            <ToolCard name={b.name} tagline={b.tag} chip={b.chip} at={secToFrame(prev) - 2} chipColor={b.tone === 'bad' ? COLORS.danger : b.tone === 'good' ? undefined : COLORS.accent2}>
              <Panel>{b.rows.map((r, j) => <Line key={j} {...r} />)}</Panel>
            </ToolCard>
          </FadeOut>
        );
      })}
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-128/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="GEMINI CACHE" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          The cheaper Gemini costs more to cache.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short128;
